p='src/assets/style.css'
s=open(p).read()
def rep(old,new,count=1):
    global s
    assert s.count(old)==count,(old,s.count(old))
    s=s.replace(old,new)

rep("""  /* DESIGN.md split-header height: content top to the first row. */
  --split-header-height: 78px;
""","""  /* DESIGN.md split-header height: content top to the first row. */
  --split-header-height: 78px;
  /* DESIGN.md content inset: where text starts in the list and the reader
     (split tabs, sender names, captions, notices, dock, reader subject and
     message text). --content-inset-end is the matching right inset (dock,
     notices, composer, reader). The older literal 50px/24px uses elsewhere
     agree with these values; new reader geometry reads the tokens. */
  --content-inset: 50px;
  --content-inset-end: 24px;
  /* One collapsed message line (12px type: 24px). The reader's message toggle
     takes this as its minimum height and the loading skeleton rows are sized
     from it, so the pane does not jump when the conversation arrives. */
  --message-row-height: calc(var(--type-body) * 2);
""")

