  flex-direction: column;
  padding: 0.5rem 0.75rem;
}""","""/* No side padding: the content inset (50px start, 24px end) is owned by the
   scroller and by the notes above it, so the reader's text sits on the same x
   as the list's. No bottom padding: a docked composer brings its own 12px
   bottom margin. */
.reader-pane {
